<?php
declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
if(!payout_automatic_enabled()||!payout_paypal_confirmed()||payment_gateway()!=='paypal'){fwrite(STDOUT,"Automatic payouts are disabled or not confirmed.\n");exit(0);}
$start=date('Y-m-01',strtotime('first day of last month'));$end=date('Y-m-t',strtotime($start));
$users=$pdo->query("SELECT u.id,u.display_name,u.paypal_email,GROUP_CONCAT(a.name ORDER BY a.name SEPARATOR ', ') artist_names FROM users u JOIN artists a ON a.owner_user_id=u.id WHERE u.is_artist=1 AND u.paypal_email IS NOT NULL AND u.paypal_email<>'' GROUP BY u.id,u.display_name,u.paypal_email ORDER BY u.id")->fetchAll();$sent=0;
foreach($users as $user){$due=payout_items_for_user((int)$user['id'],$start,$end);if((int)$due['payout_pence']<1||!filter_var((string)$user['paypal_email'],FILTER_VALIDATE_EMAIL)||empty($due['items']))continue;$payoutId=0;try{$pdo->beginTransaction();$pdo->prepare('INSERT INTO artist_payouts(artist_id,user_id,period_start,period_end,gross_pence,host_fee_pence,payout_pence,currency,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,NULL)')->execute([(int)$due['items'][0]['artist_id'],(int)$user['id'],$start,$end,$due['gross_pence'],$due['host_fee_pence'],$due['payout_pence'],paypal_config()['currency'],'processing']);$payoutId=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO artist_payout_items(payout_id,order_item_id,artist_id,gross_pence,host_fee_pence,artist_share_pence) VALUES(?,?,?,?,?,?)');foreach($due['items'] as $item)$ins->execute([$payoutId,$item['order_item_id'],$item['artist_id'],$item['gross_pence'],$item['host_fee_pence'],$item['artist_share_pence']]);$pdo->commit();$response=paypal_create_payout([['payout_id'=>$payoutId,'artist_id'=>(int)$due['items'][0]['artist_id'],'artist_name'=>$user['display_name'].' ('.$user['artist_names'].')','paypal_email'=>$user['paypal_email'],'artist_share_pence'=>$due['payout_pence']]],'recordstore-'.$start.'-user-'.(int)$user['id'].'-'.bin2hex(random_bytes(4)),paypal_config()['currency']);$pdo->prepare("UPDATE artist_payouts SET status='paid',paypal_batch_id=?,paypal_response=?,paid_at=NOW() WHERE id=?")->execute([(string)($response['batch_header']['payout_batch_id']??''),json_encode($response,JSON_UNESCAPED_SLASHES),$payoutId]);$sent++;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($payoutId)$pdo->prepare("UPDATE artist_payouts SET status='failed',error_message=? WHERE id=?")->execute([substr($e->getMessage(),0,500),$payoutId]);fwrite(STDERR,'Payout failed for user '.(int)$user['id'].': '.$e->getMessage()."\n");}}
fwrite(STDOUT,"Processed {$sent} automatic user payout(s) for {$start} to {$end}.\n");
